"use strict";(self.webpackChunkrdk_s_doc=self.webpackChunkrdk_s_doc||[]).push([[11],{508:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"link","label":"RDK X5 Application Case Guide","href":"/x5_cases_doc/en/case","docId":"case","unlisted":false},{"type":"category","label":"Getting Started Cases","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"GPIO Interface","href":"/x5_cases_doc/en/getting_started/gpio","docId":"getting_started/gpio","unlisted":false},{"type":"link","label":"PWM Interface","href":"/x5_cases_doc/en/getting_started/pwm","docId":"getting_started/pwm","unlisted":false},{"type":"link","label":"UART Interface","href":"/x5_cases_doc/en/getting_started/uart","docId":"getting_started/uart","unlisted":false},{"type":"link","label":"I2C Interface","href":"/x5_cases_doc/en/getting_started/i2c","docId":"getting_started/i2c","unlisted":false},{"type":"link","label":"SPI Interface","href":"/x5_cases_doc/en/getting_started/spi","docId":"getting_started/spi","unlisted":false},{"type":"link","label":"Earphone Audio Jack","href":"/x5_cases_doc/en/getting_started/earphone","docId":"getting_started/earphone","unlisted":false},{"type":"link","label":"USB Interface","href":"/x5_cases_doc/en/getting_started/usb","docId":"getting_started/usb","unlisted":false},{"type":"link","label":"CAN Interface","href":"/x5_cases_doc/en/getting_started/can","docId":"getting_started/can","unlisted":false}],"href":"/x5_cases_doc/en/01_getting_started"},{"type":"category","label":"Basic Cases","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Object Detection","href":"/x5_cases_doc/en/basic/detect","docId":"basic/detect","unlisted":false},{"type":"link","label":"Speech-to-Text (ASR)","href":"/x5_cases_doc/en/basic/asr","docId":"basic/asr","unlisted":false},{"type":"link","label":"Keyword Spotting (KWS)","href":"/x5_cases_doc/en/basic/kws","docId":"basic/kws","unlisted":false},{"type":"link","label":"Text-to-Speech (TTS)","href":"/x5_cases_doc/en/basic/tts","docId":"basic/tts","unlisted":false}],"href":"/x5_cases_doc/en/02_basic"},{"type":"category","label":"Intermediate Cases","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Gesture Interaction Game","href":"/x5_cases_doc/en/intermediate/gesture_game","docId":"intermediate/gesture_game","unlisted":false}],"href":"/x5_cases_doc/en/03_intermediate"},{"type":"category","label":"Advanced Cases","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Chatbot","href":"/x5_cases_doc/en/advanced/chatbot","docId":"advanced/chatbot","unlisted":false}],"href":"/x5_cases_doc/en/04_advanced"}]},"docs":{"advanced/chatbot":{"id":"advanced/chatbot","title":"Chatbot","description":"A Large Language Model (LLM) is an AI model trained with deep learning on large-scale text. It can understand, generate, reason, and answer questions in natural language. It interprets user text or speech and produces semantically appropriate replies or actions. Through pretraining and instruction tuning, it learns language knowledge and reasoning, then uses context for dialogue, content creation, task planning, code generation, and more. LLMs are a core capability for intelligent robots, smart terminals, office assistants, and AI agents. They significantly improve natural interaction, knowledge services, and intelligent decision-making.","sidebar":"docsSidebar"},"basic/asr":{"id":"basic/asr","title":"Speech-to-Text (ASR)","description":"ASR (Automatic Speech Recognition) converts spoken language into text in real time. It is a foundation for voice assistants, meeting notes, intelligent customer service, and voice input.","sidebar":"docsSidebar"},"basic/detect":{"id":"basic/detect","title":"Object Detection","description":"Object Detection is a core computer-vision task. It identifies and localizes objects in images or video (such as people, vehicles, and animals), usually with bounding boxes. It is widely used in security monitoring, autonomous driving, and industrial inspection. Representative models include YOLO, R-CNN, and DETR.","sidebar":"docsSidebar"},"basic/kws":{"id":"basic/kws","title":"Keyword Spotting (KWS)","description":"KWS (Keyword Spotting) detects a specific wake word or keyword in real time. AI algorithms continuously listen to ambient audio and, at low power, quickly detect a preset wake word so a device can leave standby and start voice interaction. KWS is a foundation for smart speakers, assistants, in-vehicle systems, smart homes, and robot voice interaction. It enables button-free wake-up, reduces power consumption, and makes interaction more convenient.","sidebar":"docsSidebar"},"basic/tts":{"id":"basic/tts","title":"Text-to-Speech (TTS)","description":"TTS (Text To Speech) synthesizes natural spoken audio from text. AI algorithms simulate human pronunciation and play the content in real time. TTS is a foundation for intelligent assistants, human-machine interaction, customer service, in-vehicle systems, and robot voice interaction. It improves how devices deliver information and interact naturally.","sidebar":"docsSidebar"},"case":{"id":"case","title":"RDK X5 Application Case Guide","description":"This document collects typical application cases for the RDK X5 platform. It is organized by increasing difficulty, from basic peripheral interfaces to on-device AI inference, then to interactive games and a multimodal chatbot, so you can get started quickly and go deeper step by step.","sidebar":"docsSidebar"},"getting_started/can":{"id":"getting_started/can","title":"CAN Interface","description":"Interface Overview","sidebar":"docsSidebar"},"getting_started/earphone":{"id":"getting_started/earphone","title":"Earphone Audio Jack","description":"Interface Overview","sidebar":"docsSidebar"},"getting_started/gpio":{"id":"getting_started/gpio","title":"GPIO Interface","description":"Interface Overview","sidebar":"docsSidebar"},"getting_started/i2c":{"id":"getting_started/i2c","title":"I2C Interface","description":"Interface Overview","sidebar":"docsSidebar"},"getting_started/pwm":{"id":"getting_started/pwm","title":"PWM Interface","description":"Interface Overview","sidebar":"docsSidebar"},"getting_started/spi":{"id":"getting_started/spi","title":"SPI Interface","description":"Interface Overview","sidebar":"docsSidebar"},"getting_started/uart":{"id":"getting_started/uart","title":"UART Interface","description":"Interface Overview","sidebar":"docsSidebar"},"getting_started/usb":{"id":"getting_started/usb","title":"USB Interface","description":"Interface Overview","sidebar":"docsSidebar"},"intermediate/gesture_game":{"id":"intermediate/gesture_game","title":"Gesture Interaction Game","description":"Gesture interaction uses computer vision and AI to recognize hand motion, posture, and intent, then converts them into control commands a device can understand. A camera captures the gesture, and algorithms analyze and recognize it in real time for device control, command input, and state switching. Gesture interaction is an important input method for intelligent robots, human-machine collaboration, smart terminals, and virtual reality. It makes operation more convenient and more intelligent.","sidebar":"docsSidebar"}}}}')}}]);